from pathlib import Path as _HalPath


class _OfflineHal:
    """In-process HAL so Store DatabaseBlock can cursor() without a live store.

    Passing None made the tasting-room suite fail with
    ``'NoneType' object has no attribute 'cursor'`` after construct succeeded.
    """

    def __init__(self, db_path):
        self._db_path = db_path
        self._conn = None
        self.config = {}

    def _connect(self):
        if self._conn is None:
            parent = _HalPath(self._db_path).parent
            parent.mkdir(parents=True, exist_ok=True)
            self._conn = _sqlite3.connect(self._db_path, check_same_thread=False)
            self._conn.row_factory = _sqlite3.Row
        return self._conn

    @property
    def connection(self):
        return self._connect()

    def get_connection(self):
        return self._connect()

    def cursor(self):
        return self._connect().cursor()

    def execute(self, *args, **kwargs):
        return self._connect().execute(*args, **kwargs)

    def executemany(self, *args, **kwargs):
        return self._connect().executemany(*args, **kwargs)

    def commit(self):
        self._connect().commit()

    def close(self):
        if self._conn is not None:
            self._conn.close()
            self._conn = None


def _offline_hal():
    root = _HalPath(_os.environ.get("STORAGE_PATH") or ".").resolve()
    root.mkdir(parents=True, exist_ok=True)
    return _OfflineHal(str(root / "store_blocks.sqlite"))


def _ensure_store_block_ready(instance):
    """DatabaseBlock only opens SQLite in _legacy_initialize.

    Construct-with-HAL is not enough: process() uses self._connection,
    which stays None until initialize runs. LotDesk pilot then died on
    Insert failed: 'NoneType' object has no attribute 'cursor'.
    """
    conn = getattr(instance, "_connection", None)
    init = getattr(instance, "_legacy_initialize", None)
    if conn is None and callable(init):
        import asyncio
        try:
            asyncio.get_running_loop()
        except RuntimeError:
            asyncio.run(init())
            return instance
        import concurrent.futures
        with concurrent.futures.ThreadPoolExecutor() as pool:
            pool.submit(asyncio.run, init()).result()

"""Tank fermentation tracking.

Track a fermentation tank through crush and fermentation: the lot in it, its fill volume, and the Brix/temperature readings, cap management and punch-down work that move it toward dry.

Every bound Store block is invoked through app.domain_blocks.run_declared_blocks --
one loop, action passed as a KEYWORD, never inside the payload dict -- and this
capability's own decision (the fermentation stage the readings describe (inoculation, active, slow, stuck, dry) and whether a punch-down is due) is computed here, in its own module.
A fatal block refusal is returned as this capability's refusal (ok=false) and
nothing is published as a success.

READS   the caller payload, app.formulas, app.block_inputs, app.dispatch
        (through app.domain_blocks), app.authority.
WRITES  its return envelope only -- the ROUTE owns the tenant-scoped save.
NEVER   NEVER invents a reading, NEVER rewrites a block refusal to ok, NEVER
        persists a record (a handler has no tenant), NEVER types a currency
        or a rate into code.

Written by the factory WRITER role (codewhale exec)
"""

