def _f(value: Any, default: float = 0.0) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _present(value: Any) -> bool:
    if value is None:
        return False
    return str(value).strip() != ""


def _invariant(record: Dict[str, Any]) -> str | None:
    """A record that cannot be true is refused, never acted on.

    Checked on the values the caller DID supply -- the factory envelope is the
    required contract, so a missing anchor is not an error here.
