def _derive(record: Dict[str, Any]) -> Dict[str, Any]:
    """This tank's fermentation stage and punch-down schedule, from its own readings."""
    progress = formulas.fermentation_progress(record.get("brix_start"),
                                              record.get("brix_current"))
    stage = "inoculation"
    if _present(record.get("brix_current")):
        drop = _f(progress.get("drop"))
        if _f(record.get("brix_current")) <= 0.5:
            stage = "dry"
        elif drop >= 12:
            stage = "active"
        elif drop <= 1:
            stage = "slow"
        else:
            stage = "active"
    if str(record.get("stage") or ""):
        stage = str(record.get("stage"))
    punch_down_due = bool(record.get("punch_down_done")) is False and stage in ("active", "slow")
    return {"stage": stage, "fermentation": progress, "punch_down_due": punch_down_due,
            "tank": str(record.get("tank_id") or record.get("tank_name") or record.get("reference") or "")}


