at is\\n    stored. A caller who DOES present a token is refused 401 by name when it\\n    is not bound to a tenant: they are claiming an identity, and the platform\\n    says it does not know it.\\n\\n    Writes keep the plain 401 (app.auth.require_platform_token): a request\\n    that cannot be attributed to a tenant must never be allowed to act.\\n    \\\"\\\"\\\"\\n    import app.tenancy as tenancy\\n\\n    if not credential_presented(request):\\n        # Credential-less READ (verdict of the PRODUCT round-trip probe and the\\n        # documented existence-privacy rule): the platform cannot bind this\\n        # caller to any tenant, so from where they stand the collection does\\n        # not exist. A 401 here is measured as \\\"stored the record, then GET\\n        # answered HTTP 401\\\" by the one-record round-trip gate, and it also\\n        # confirms which capabilities exist to a caller who presented nothing.\\n        # The WRITE path keeps the plain 401 (require_platform_token): a\\n        # request that cannot be attributed to a tenant must never act.\\n        raise HTTPException(status_code=404, detail=\\\"not found\\\")\\n    try:\\n        return tenancy.resolve_tenant(request.headers)\\n    except tenancy.TenantRefused:\\n        # A caller who DID present a credential is claiming an identity. The\\n        # platform says it does not know that identity: 401 by name, never a\\n        # silent fall back to a default tenant.\\n        raise HTTPException(status_code=401, detail=\\\"authentication_required\\\")\\n\"},{\"type\":\"tool_result\",\"tool_use_id\":\"call_02_1cLonvkKsTGedTw0jVmJ4614\",\"content\":\"\\\"\\\"\\\"Declared placeholder connectors, answered as a typed refusal.\\n\\nWritten by the factory WRITER role (codewhale exec)\\n\\nA capability whose blueprint declares a placeholder connector cannot perform\\nits real outbound round trip until the operator supplies the connector's\\ncredential. It answers HTTP 503 with ``error_kind: \\\"unavailable\\\"`` naming the\\nsetting it needs -- BEFORE the handler runs -- and stores nothing. A fabricated\\n\\\"shipped\\\" answer would be worse than the refusal: the operator would believe a\\ncarrier had the parcel.\\n\\nREADS   the process environment.\\nWRITES  nothing.\\nNEVER   NEVER invents a credential, NEVER stores a record, NEVER answers 200\\n        for work the connector did not do.\\n\\\"\\\"\\\"\\n\\nfrom __future__ import annotations\\n\\nimport os\\nfrom typing import Any, Dict, List, Optional\\n\\n#: capability -> (connector, setting the operator must supply)\\nPLACEHOLDER_CONNECTORS: Dict[str, List[Dict[str, str]]] = {\\n    \\\"wine_club_member_shipments\\\": [\\n        {\\\"connector\\\": \\\"carrier_shipping_api\\\", \\\"setting\\\": \\\"CARRIER_SHIPPING_API_CREDENTIALS\\\"},\\n    ],\\n}\\n\\n\\ndef _configured(setting: str) -> bool:\\n    return bool((os.environ.get(setting) or \\\"\\\").strip())\\n\\n\\ndef missing(capability_id: str) -> List[Dict[str, str]]:\\n    \\\"\\\"\\\"The declared connectors of this capability that have no credential.\\\"\\\"\\\"\\n    return [c for c in PLACEHOLDER_CONNECTORS.get(str(capability_id or \\\"\\\"), [])\\n            if not _configured(c[\\\"setting\\\"])]\\n\\n\\ndef refusal_for(capability_id: str) -> Optional[Dict[str, Any]]:\\n    \\\"\\\"\\\"The typed refusal this capability owes, or None when it can run.\\\"\\\"\\\"\\n    absent = missing(capability_id)\\n    if not absent:\\n        return None\\n    return {\\n        \\\"ok\\\": False,\\n        \\\"capability\\\": str(capability_id),\\n        \\\"error_kind\\\": \\\"unavailable\\\",\\n        \\\"refused\\\": True,\\n        \\\"error\\\": \\\"declared placeholder connector(s) not configured\\\",\\n        \\\"connectors\\\": [c[\\\"connector\\\"] for c in absent],\\n        \\\"settings\\\": [c[\\\"setting\\\"] for c in absent],\\n    }\\n\"},{\"type\":\"tool_result\",\"tool_use_id\":\"call_03_vBTU8C6eEugg52PVDPl04382\",\"content\":\"E